using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using Takupoke.Core;
using Takupoke.Infrastructure.Parsing;
using Takupoke.Infrastructure.Recovery;

namespace Takupoke.Integration.Tests;

internal static class CapturedOcrHeaderFixture
{
    // Exact five-page returned glyphs/rules from one frozen v3 OCR run,
    // plus original lossless BGRA. No model invocation or repaired text.
    // Full console SHA f136400c65a3729d431fafb86dbb246e9779e29128ac7b2b533356bddfff947f; original PDF233dec852ec7...
    internal static (PdfPageLayout[] Pages, RecoveryRaster[] Rasters, string PdfHash) Load()
    {
        const string packed = "";
        using var input = new MemoryStream(Convert.FromBase64String(packed));
        using var gzip = new GZipStream(input, CompressionMode.Decompress);
        using var output = new MemoryStream(); gzip.CopyTo(output);
        var bytes = output.ToArray();
        if (bytes.Length != 5661796 || Convert.ToHexStringLower(SHA256.HashData(bytes)) != "9966f271f0bde4bb237328baab2dd57d02cfb0625cf539e271c234fd3108d533")
            throw new InvalidDataException("Captured original OCR fixture changed.");
        using var document = JsonDocument.Parse(bytes);
        var pages = new List<PdfPageLayout>(); var rasters = new List<RecoveryRaster>();
        foreach (var page in document.RootElement.GetProperty("pages").EnumerateArray())
        {
            var pixels = page.GetProperty("bgra").GetBytesFromBase64();
            if (Convert.ToHexStringLower(SHA256.HashData(pixels)) != page.GetProperty("bgraSha256").GetString())
                throw new InvalidDataException("Original BGRA changed.");
            var raster = new RecoveryRaster(page.GetProperty("width").GetInt32(), page.GetProperty("height").GetInt32(), pixels);
            if (!raster.Valid) throw new InvalidDataException("Original dimensions changed.");
            rasters.Add(raster);
            pages.Add(new(raster.Width, raster.Height,
                JsonSerializer.Deserialize<PdfGlyph[]>(page.GetProperty("glyphs").GetRawText())!,
                JsonSerializer.Deserialize<PdfRule[]>(page.GetProperty("rules").GetRawText())!));
        }
        if (pages.Count != 5) throw new InvalidDataException("Five captured pages required.");
        return (pages.ToArray(), rasters.ToArray(), document.RootElement.GetProperty("pdfSha256").GetString()!);
    }
    internal static Takupoke.Core.Recovery.RecoveryDocument Build(PdfPageLayout[] pages, RecoveryRaster[] rasters, string pdfHash,
        IReadOnlySet<int>? ocrPages)
    {
        // Blank proof scans ORIGINAL pixels using ORIGINAL physical rules,
        // even when a test introduces an adversarial layout/rule declaration.
        var scanners = rasters.Select(r => r.InkFreeScanner(r.RuleMask(r.Rules()))).ToArray();
        return RecoveryDocumentBuilder.Build(pdfHash, MaterialKind.Timetable, pages,
            (page, box) => scanners[page - 1](box), ocrPages, allowStructureProposal: true);
    }
}
